class TrieNode { constructor(){ this.next = new Map(); this.pass = 0; this.end = 0; } }
class TrieDict { constructor(){ this.root = new TrieNode(); }
 insertWord(w){ let p=this.root; for(const ch of w){ if(!p.next.has(ch)) p.next.set(ch,new TrieNode()); p=p.next.get(ch); p.pass++; } p.end++; }
